import re

_PORT = re.compile(r" *([0-9]+) *")


def parse_port(text):
    if not isinstance(text, str):
        raise ValueError("port must be a string")
    m = _PORT.fullmatch(text)  # fullmatch: "$" would accept a trailing newline
    if not m:
        raise ValueError(f"invalid port: {text!r}")
    port = int(m.group(1))
    if not 1 <= port <= 65535:
        raise ValueError(f"port out of range: {port}")
    return port

import unittest

from solution import parse_port


class ParsePortTest(unittest.TestCase):
    def test_valid(self):
        for text, want in [("1", 1), ("65535", 65535), ("  80  ", 80),
                           ("0008", 8), ("000065535", 65535)]:
            self.assertEqual(parse_port(text), want)
            self.assertIs(type(parse_port(text)), int)

    def test_invalid(self):
        bad = ["", " ", "0", "000", "65536", "99999999999", "+80", "-80",
               "80\n", "\t80", "8 0", "80.0", "8.", "٨٠",
               "８０", "0x50", "abc", "80 "]
        for text in bad:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_port(text)

    def test_non_string(self):
        for v in [None, 80, 80.0, b"80", ["80"]]:
            with self.assertRaises(ValueError):
                parse_port(v)


if __name__ == "__main__":
    unittest.main()

