def parse_port(text):
    """Parse an ASCII decimal string (1-65535, optional surrounding spaces) into an int."""
    if not isinstance(text, str):
        raise ValueError("port must be a string")
    digits = text.strip(" ")
    if not digits:
        raise ValueError("empty port")
    if not all("0" <= c <= "9" for c in digits):
        raise ValueError("port must contain only ASCII digits")
    value = int(digits)
    if not 1 <= value <= 65535:
        raise ValueError("port out of range 1-65535")
    return value

