from solution import parse_port


class ParsePortTests(unittest.TestCase):
    def test_boundaries(self):
        self.assertEqual(parse_port("1"), 1)
        self.assertEqual(parse_port("65535"), 65535)
        self.assertEqual(parse_port("80"), 80)

    def test_out_of_range(self):
        for s in ["0", "00", "65536", "99999", "100000000000000000000"]:
            with self.subTest(s=s):
                with self.assertRaises(ValueError):
                    parse_port(s)

    def test_spaces_and_leading_zeros(self):
        self.assertEqual(parse_port("  8080  "), 8080)
        self.assertEqual(parse_port("0001"), 1)
        self.assertEqual(parse_port("065535"), 65535)
        self.assertEqual(parse_port(" 7"), 7)

    def test_returns_int(self):
        self.assertIs(type(parse_port("22")), int)

    def test_invalid_strings(self):
        bad = ["", " ", "   ", "+80", "-80", "80\n", "\n80", "\t80", "80\t",
               "80\r", "8 0", "80.0", "80.", ".5", "٣٤",
               "８０", "8 ", "0x50", "1e3", "abc", "80a", "_80"]
        for s in bad:
            with self.subTest(s=s):
                with self.assertRaises(ValueError):
                    parse_port(s)

    def test_non_strings(self):
        for v in [None, 80, 80.0, b"80", bytearray(b"80"), True, ["80"]]:
            with self.subTest(v=v):
