def merge_intervals(intervals):
    """Merge closed integer intervals; return a new sorted list of [start, end].

    Touching intervals (e.g. [1,3] and [3,5]) merge; [1,3] and [4,5] do not.
    The input list and its pairs are not modified.

    Time: O(n log n) for sorting; space: O(n) for the output and sorted copy.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: p[0]):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
