import copy
import os
import sys
import unittest

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from solution import merge_intervals


class MergeIntervalsTest(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]), [])

    def test_single(self):
        self.assertEqual(merge_intervals([[2, 5]]), [[2, 5]])

    def test_touching_merges(self):
        self.assertEqual(merge_intervals([[1, 3], [3, 5]]), [[1, 5]])

    def test_gap_does_not_merge(self):
        self.assertEqual(merge_intervals([[1, 3], [4, 5]]), [[1, 3], [4, 5]])

    def test_unsorted(self):
        self.assertEqual(merge_intervals([[8, 10], [1, 3], [2, 6]]), [[1, 6], [8, 10]])

    def test_containment(self):
        self.assertEqual(merge_intervals([[1, 10], [2, 3], [4, 5]]), [[1, 10]])
        self.assertEqual(merge_intervals([[2, 3], [1, 10]]), [[1, 10]])

    def test_duplicates(self):
        self.assertEqual(merge_intervals([[1, 2], [1, 2], [1, 2]]), [[1, 2]])

    def test_negative(self):
        self.assertEqual(merge_intervals([[-5, -2], [-3, 1], [4, 4]]), [[-5, 1], [4, 4]])

    def test_point_intervals(self):
        self.assertEqual(merge_intervals([[3, 3], [3, 3], [2, 2]]), [[2, 2], [3, 3]])

    def test_input_unchanged(self):
        data = [[5, 6], [1, 3], [2, 4], [1, 3]]
        snapshot = copy.deepcopy(data)
        result = merge_intervals(data)
        self.assertEqual(data, snapshot)
        result[0][1] = 999
