from collections import deque


def topological_order(nodes, edges):
    """Kahn's algorithm. O(V + E) time and space. Raises ValueError on a cycle."""
    succ = {n: set() for n in nodes}  # set dedupes repeated edges
    for a, b in edges:
        succ[a].add(b)
    indeg = dict.fromkeys(succ, 0)
    for outs in succ.values():
        for b in outs:
            indeg[b] += 1
    queue = deque(n for n in nodes if indeg[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for b in succ[n]:
            indeg[b] -= 1
            if indeg[b] == 0:
                queue.append(b)
    if len(order) != len(succ):
        raise ValueError("graph contains a cycle")
    return order
