from collections import deque


def topological_order(nodes, edges):
    """Return a topological ordering of nodes; raise ValueError on a cycle.

    Kahn's algorithm. Duplicate edges are collapsed so they don't inflate
    in-degrees. Inputs are not mutated.
    Time O(V + E), space O(V + E).
    """
    succ = {n: set() for n in nodes}
    indeg = {n: 0 for n in nodes}
    for a, b in edges:
        if b not in succ[a]:
            succ[a].add(b)
            indeg[b] += 1

    queue = deque(n for n in nodes if indeg[n] == 0)
    order = []
    while queue:
        n = queue.popleft()
        order.append(n)
        for m in succ[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                queue.append(m)

    if len(order) != len(indeg):
        raise ValueError("graph contains a cycle")
    return order

