def _parse_csv(text):
    """Strict RFC 4180-style parser; returns a list of rows (lists of str)."""
    rows, row, field = [], [], []
    i, n = 0, len(text)
    quoted = False      # inside a quoted field
    closed = False      # just after a closing quote
    started = False     # current record has any content
    while i < n:
        c = text[i]
        if quoted:
            if c == '"':
                if text[i + 1:i + 2] == '"':
                    field.append('"')
                    i += 1
                else:
                    quoted, closed = False, True
            else:
                field.append(c)
        elif c == ",":
            row.append("".join(field))
            field, closed, started = [], False, True
        elif c in "\r\n":
            if c == "\r" and text[i + 1:i + 2] == "\n":
                i += 1
            row.append("".join(field))
            rows.append(row)
            row, field, closed, started = [], [], False, False
        elif closed:
            raise ValueError("unexpected character after closing quote")
        elif c == '"':
            if field:
                raise ValueError("quote inside unquoted field")
            quoted = True
            started = True
        else:
            field.append(c)
            started = True
        i += 1
    if quoted:
        raise ValueError("unterminated quoted field")
    if started:
        row.append("".join(field))
        rows.append(row)
    return rows


def read_people(text):
    """Parse CSV text with header name,age into a list of dicts."""
    rows = _parse_csv(text)
    if not rows or rows[0] != ["name", "age"]:
        raise ValueError("header must be exactly name,age")
    people = []
    for row in rows[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}")
        name, age = row
        if not (age.isascii() and age.isdigit()):
            raise ValueError(f"invalid age: {age!r}")
        value = int(age)
        if value > 130:
            raise ValueError(f"age out of range: {value}")
        people.append({"name": name, "age": value})
    return people
