async function collectPages(fetchPage) {
  const items = [];
  const seen = new Set();
  let cursor = null;
  do {
    if (cursor !== null) {
      if (seen.has(cursor)) throw new Error(`Repeated cursor: ${JSON.stringify(cursor)}`);
      seen.add(cursor);
    }
    const page = await fetchPage(cursor);
    items.push(...page.items);
    cursor = page.next;
  } while (cursor !== null);
  return items;
}

