'use strict';

const UNSAFE = new Set(['__proto__', 'constructor', 'prototype']);

const isPlain = (v) => {
  if (v === null || typeof v !== 'object') return false;
  const p = Object.getPrototypeOf(v);
  return p === Object.prototype || p === null;
};

// Deep copy that also rejects unsafe own keys at any depth.
function clone(v) {
  if (Array.isArray(v)) return v.map(clone);
  if (!isPlain(v)) return v;
  const out = {};
  for (const k of Object.keys(v)) {
    if (UNSAFE.has(k)) throw new Error(`Unsafe key: ${k}`);
    out[k] = clone(v[k]);
  }
  return out;
}

// Merges two already-cloned values; the result reuses only those fresh clones.
function merge(a, b) {
  if (!isPlain(a) || !isPlain(b)) return b;
  for (const k of Object.keys(b)) a[k] = k in a ? merge(a[k], b[k]) : b[k];
  return a;
}

function mergeConfig(base, override) {
  return merge(clone(base), clone(override));
}

module.exports = { mergeConfig };
