    if (typeof value === 'function' || typeof value === 'symbol') {
      throw new TypeError('Unsupported value type: ' + typeof value);
    }
    return value;
  }
  if (stack.has(value)) throw new TypeError('Circular structure is not supported');
  stack.add(value);
