  if (isPlainObject(base) && isPlainObject(override)) {
    // Validate both sides fully (including keys that will be replaced).
    const result = clone(base, new Set());
    for (const key of Object.getOwnPropertyNames(override)) {
      if (UNSAFE_KEYS.has(key)) throw new Error('Unsafe key rejected: ' + key);
    }
    for (const key of Object.keys(override)) {
      result[key] = Object.prototype.hasOwnProperty.call(result, key)
        ? merge(base[key], override[key], stack)
        : clone(override[key], new Set());
    }
