  if (!ok(total) || total < 0) throw new RangeError('total must be a nonnegative safe integer');
  if (!Array.isArray(weights) || weights.length === 0) throw new RangeError('weights must be a nonempty array');
  let sum = 0;
  for (const w of weights) {
    if (!ok(w) || w <= 0) throw new RangeError('weights must be positive safe integers');
    sum += w;
    if (!ok(sum) || !ok(total * w)) throw new RangeError('values exceed safe integer range');
  }
  const rem = [];
  const out = weights.map((w, i) => {
    const p = total * w; // exact: checked safe above
    rem[i] = p % sum;
    return (p - rem[i]) / sum;
  });
  let left = total - out.reduce((a, b) => a + b, 0);
  const order = weights.map((_, i) => i).sort((a, b) => rem[b] - rem[a] || a - b);
  for (let k = 0; k < left; k++) out[order[k]]++;
  return out;
}

