from datetime import datetime, timezone


def utc_day_start(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    # shortcut: Z handled by hand for Python < 3.11, drop when 3.11+ is the floor
    if text[-1:] in ("Z", "z"):
        text = text[:-1] + "+00:00"
    dt = datetime.fromisoformat(text)  # raises ValueError on invalid input
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError("timestamp must include a UTC offset")
    return dt.astimezone(timezone.utc).replace(hour=0, minute=0, second=0, microsecond=0)

import unittest
from datetime import datetime, timezone

from solution import utc_day_start


def d(*a):
    return datetime(*a, tzinfo=timezone.utc)


class UtcDayStartTest(unittest.TestCase):
    def test_positive_offset_goes_to_previous_day(self):
        self.assertEqual(utc_day_start("2025-01-01T00:30:00+02:00"), d(2024, 12, 31))

    def test_negative_offset_goes_to_next_day(self):
        self.assertEqual(utc_day_start("2025-12-31T22:00:00-05:00"), d(2026, 1, 1))

    def test_z_suffix(self):
        self.assertEqual(utc_day_start("2025-06-15T23:59:59Z"), d(2025, 6, 15))

    def test_leap_day(self):
        self.assertEqual(utc_day_start("2024-02-29T12:00:00Z"), d(2024, 2, 29))
        self.assertEqual(utc_day_start("2024-03-01T01:00:00+02:00"), d(2024, 2, 29))
        self.assertEqual(utc_day_start("2024-02-28T23:00:00-02:00"), d(2024, 2, 29))

    def test_result_tz_is_utc(self):
        self.assertIs(utc_day_start("2025-01-01T00:00:00+05:30").tzinfo, timezone.utc)

    def test_naive_rejected(self):
        with self.assertRaises(ValueError):
            utc_day_start("2025-01-01T00:30:00")

    def test_invalid_rejected(self):
        for bad in ("", "garbage", "2025-02-30T00:00:00Z", None):
            with self.assertRaises(ValueError):
                utc_day_start(bad)


if __name__ == "__main__":
    unittest.main()

