from datetime import datetime, timezone


def utc_day_start(text):
    """Return UTC midnight of the UTC calendar day containing the instant `text`.

    `text` must be an ISO 8601 timestamp with a "Z" or numeric UTC offset.
    Naive timestamps and invalid input raise ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("timestamp must be a string")
    s = text.strip()
    if s[-1:] in ("Z", "z"):
        s = s[:-1] + "+00:00"
    try:
        dt = datetime.fromisoformat(s)
    except ValueError as e:
        raise ValueError(f"invalid ISO 8601 timestamp: {text!r}") from e
    if dt.tzinfo is None or dt.utcoffset() is None:
        raise ValueError(f"timestamp has no UTC offset: {text!r}")
    utc = dt.astimezone(timezone.utc)
    return utc.replace(hour=0, minute=0, second=0, microsecond=0)
