const RE = /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/;

function parse(v) {
  const m = typeof v === 'string' && RE.exec(v);
  if (!m) throw new TypeError(`Invalid version: ${v}`);
  return m.slice(1);
}

function compareVersion(a, b) {
  const x = parse(a);
  const y = parse(b);
  for (let i = 0; i < 3; i++) {
    // no leading zeros, so longer means larger; equal length compares lexicographically
    if (x[i].length !== y[i].length) return x[i].length < y[i].length ? -1 : 1;
    if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
  }
  return 0;
}

module.exports = { compareVersion };
