// Compare canonical decimal strings: longer means larger, else lexicographic.
function compareDecimal(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

