'use strict';

class Emitter {
  constructor() {
    // event -> Map(fn -> registration); Map keeps registration order
    this._events = new Map();
  }

  on(event, fn) {
    let listeners = this._events.get(event);
    if (!listeners) {
      listeners = new Map();
      this._events.set(event, listeners);
    }
    let reg = listeners.get(fn);
    if (!reg) {
      reg = { fn };
      listeners.set(fn, reg);
    }
    // Only removes this registration, so a stale call can't remove a later re-registration.
    return () => {
      const current = this._events.get(event);
      if (current && current.get(fn) === reg) this._remove(event, fn);
    };
  }

  off(event, fn) {
    this._remove(event, fn);
  }

  emit(event, value) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    for (const fn of Array.from(listeners.keys())) fn(value);
  }

  _remove(event, fn) {
    const listeners = this._events.get(event);
    if (!listeners) return;
    listeners.delete(fn);
    if (listeners.size === 0) this._events.delete(event);
  }
}

module.exports = { Emitter };
EOF
